script:
frappe.ui.form.on('Service Ticket', {
    refresh(frm) {
        if (frm.is_new()) return;

        const requests = frm.doc.custom_movement_requests || [];
        if (!requests.length) return;

        const roles = ['Maintenance Manager', 'TP Manager', 'System Manager'];
        if (!roles.some(role => frappe.user.has_role(role))) return;

        frm.add_custom_button(
            __('Manage Movement Requests'),
            () => open_movement_manager(frm),
            __('Relocation')
        );
    }
});

function open_movement_manager(frm) {
    const rows = frm.doc.custom_movement_requests || [];

    const transitions = {
        'Requested': ['Approve', 'Reject', 'Cancel'],
        'Approved': ['Mark Planned', 'Cancel'],
        'Planned': ['Cancel']
    };

    const labels = rows.map((row, index) => {
        const item = row.custom_component || row.custom_equipment || 'Unspecified';
        return `${index + 1}. ${item} [${row.custom_request_status || 'Requested'}]`;
    });

    let dialog;

    function selected_row() {
        const label = dialog.get_value('request');
        const index = labels.indexOf(label);
        return index >= 0 ? rows[index] : null;
    }

    function update_actions() {
        const row = selected_row();
        const status = row && (row.custom_request_status || 'Requested');
        const actions = transitions[status] || [];

        dialog.set_df_property('action', 'options', [''].concat(actions).join('\n'));
        dialog.set_value('action', '');
    }

    dialog = new frappe.ui.Dialog({
        title: __('Manage Movement Requests'),
        fields: [
            {
                fieldname: 'request',
                label: __('Movement Request'),
                fieldtype: 'Select',
                options: labels.join('\n'),
                reqd: 1,
                onchange: update_actions
            },
            {
                fieldname: 'action',
                label: __('RM Action'),
                fieldtype: 'Select',
                options: '',
                reqd: 1
            }
        ],
        primary_action_label: __('Apply Action'),
        primary_action(values) {
            const row = selected_row();
            if (!row) return;

            const allowed = transitions[row.custom_request_status || 'Requested'] || [];
            if (!allowed.includes(values.action)) {
                frappe.msgprint(__('This action is not available.'));
                return;
            }

            frappe.confirm(
                __(`Apply "${values.action}" to movement request ${row.name}?`),
                () => {
                    frappe.call({
                        method: 'maintenance_app.movement_request.change_movement_request_status',
                        args: {
                            ticket: frm.doc.name,
                            request_name: row.name,
                            action: values.action
                        },
                        freeze: true,
                        callback(r) {
                            if (!r.message) return;

                            dialog.hide();
                            frappe.show_alert({
                                message: __('Movement Request updated'),
                                indicator: 'green'
                            });
                            frm.reload_doc();
                        }
                    });
                }
            );
        }
    });

    dialog.show();
    dialog.set_value('request', labels[0] || '');
    update_actions();
}
